<?php

declare(strict_types=1);

namespace App\Analyzer;

use App\Analyzer\Graph\Edge\Usage\MethodCallEdge;
use App\Analyzer\Graph\Edge\Usage\UnresolvedCallEdge;
use App\Analyzer\Graph\FileMeta;
use App\Analyzer\Graph\Graph;
use App\Analyzer\Graph\Node\FunctionNode;
use App\Analyzer\Graph\Node\MethodNode;
use App\Analyzer\Graph\Node\UnknownNode;
use App\Analyzer\Graph\NodeId\MethodNodeId;
use App\Analyzer\Graph\NodeId\UnknownNodeId;
use App\Analyzer\Graph\Resolution\ClassHierarchy;
use App\Analyzer\Graph\Resolution\TypeConstraint;
use PhpParser\Node;
use PhpParser\Node\Expr;
use PhpParser\PrettyPrinter\Standard;

/** Records receiver calls against the same declarations for either analysis engine. */
final readonly class BodyCallRecorder
{
    public function __construct(private Graph $graph, private ClassHierarchy $hierarchy) {}

    /** @param list<Node> $body */
    public function record(array $body, MethodNode|FunctionNode $source): void
    {
        $types = new ReceiverTypes($this->hierarchy, $source);
        $nodes = $this->expressions($body);
        foreach ($nodes as $node) {
            if ($node instanceof Expr\Assign) {
                $types->assign($node);
            }
        }
        foreach ($nodes as $node) {
            if ($node instanceof Expr\MethodCall || $node instanceof Expr\NullsafeMethodCall) {
                $this->call($node, $source, $types);
            }
        }
    }

    /** @param list<Node> $nodes
     * @return list<Node>
     */
    private function expressions(array $nodes): array
    {
        $found = [];
        foreach ($nodes as $node) {
            if ($node instanceof Node\Stmt\ClassLike || $node instanceof Node\Stmt\Function_) {
                continue;
            }
            $found[] = $node;
            foreach ($node->getSubNodeNames() as $name) {
                $child = $node->{$name};
                $children = is_array($child) ? array_filter($child, static fn (mixed $value): bool => $value instanceof Node) : ($child instanceof Node ? [$child] : []);
                array_push($found, ...$this->expressions(array_values($children)));
            }
        }

        return $found;
    }

    private function call(Expr\MethodCall|Expr\NullsafeMethodCall $call, MethodNode|FunctionNode $source, ReceiverTypes $types): void
    {
        // The engine already records calls on $this, with the original lexical owner.
        if ($call->var instanceof Expr\Variable && $call->var->name === 'this' && $call->name instanceof Node\Identifier) {
            return;
        }
        $file = $source->meta()?->path;
        if ($file === null) {
            return;
        }
        $meta = new FileMeta($file, $call->getStartLine(), 1, $call->getStartFilePos());
        $receiver = $types->of($call->var);
        $owners = TypeConstraint::of($receiver)->names();
        if ($owners === [] || !$call->name instanceof Node\Identifier) {
            $target = new UnknownNode(new UnknownNodeId('unresolved-call@'.$file.':'.$call->getStartFilePos()), false, $meta);
            $this->graph->addNode($target);
            $this->graph->addEdge(new UnresolvedCallEdge($source, $target, $meta, (new Standard())->prettyPrintExpr($call)));

            return;
        }
        foreach ($owners as $owner) {
            $target = $this->hierarchy->method($owner, $call->name->toString())
                ?? new MethodNode(MethodNodeId::of($owner, $call->name->toString()));
            $this->graph->addNode($target);
            $this->graph->addEdge(new MethodCallEdge($source, $target, $meta, $receiver));
        }
    }
}
